from collections import defaultdict, deque

adj = defaultdict(set)
for u, v in edges:
    adj[u].add(v)
    adj[v].add(u)

def is_connected_after_removing(vertices_to_remove):
    remaining = [v for v in range(12) if v not in vertices_to_remove]
    if len(remaining) == 0:
        return True

    visited = set()
    queue = deque([remaining[0]])
    visited.add(remaining[0])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if v not in vertices_to_remove and v not in visited:
                visited.add(v)
                queue.append(v)

    return len(visited) == len(remaining)

# Check all subsets of size 3
connected_after_3 = True
for subset in itertools.combinations(range(12), 3):
    if not is_connected_after_removing(set(subset)):
        print(f"Disconnected after removing {subset}")
        connected_after_3 = False
        break

print(f"Connected after removing any 3 vertices: {connected_after_3}")

